Q: Are there any API that allow to retrieve the musicians involved in a certain album/track? A: <p>The following code uses the <a href="https://wiki.musicbrainz.org/MusicBrainz_API" rel="nofollow noreferrer">MusicBrainz API</a> to find all artist relations of <a href="https://musicbrainz.org/release-group/780e6a16-9384-307d-ae65-02e1d6313753" rel="nofollow noreferrer">Queen - Made in Heaven</a>.
It uses <a href="https://github.com/Borewit/musicbrainz-api" rel="nofollow noreferrer">musicbrainz-api</a>, a module I wrote, to ease communication with the <a href="https://wiki.musicbrainz.org/MusicBrainz_API" rel="nofollow noreferrer">MusicBrainz API</a>.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>/**
 * Find release-group for artist and release title.
 */
async function findReleaseGroup(mbApi, artist, title) {
  const query = `artist:"${artist}" AND release:"${title}"`;
  console.log(`Resolving release group: ${query}`);

  const result = await mbApi.search('release-group', {
    query
  });
  return result.count &gt; 0 ? result['release-groups'][0] : undefined;
}

/**
 * Find all related artists for a release-group.
 */
async function findAllRelatedArtists(mbApi, mbidReleaseGroup) {
  const releaseGroup = await mbApi.lookup(
    'release-group',
    mbidReleaseGroup,
    ['releases']
  );

  const release = releaseGroup.releases?.[0];
  if (!release) {
    throw new Error('The release group contains no releases.');
  }

  console.log(`Using Release MBID=${release.id}`);

  // recording-level-rels puts recording relationships directly on
  // each track.recording object.
  const releaseWithRelations = await mbApi.lookup(
    'release',
    release.id,
    ['recordings', 'recording-level-rels', 'artist-rels']
  );

  const seenRelations = new Set();

  for (const medium of releaseWithRelations.media ?? []) {
    for (const track of medium.tracks ?? []) {
      for (const relation of track.recording.relations ?? []) {
        if (!relation.artist) {
          continue;
        }

        const relationKey =
          `${relation['type-id']}/${relation.artist.id}`;

        if (!seenRelations.has(relationKey)) {
          seenRelations.add(relationKey);
          console.log(
            `Relation: ${relation.artist.name} (${relation.type})`
          );
        }
      }
    }
  }

  console.log('Printed all relations present in MusicBrainz API.');
}

async function resolveArtists() {
  console.log('Loading musicbrainz-api...');

  const {
    MusicBrainzApi
  } = await import(
    'https://cdn.jsdelivr.net/npm/musicbrainz-api@0.25.1/+esm'
  );

  const mbApi = new MusicBrainzApi({
    appName: 'stackoverflow.com/questions/74498924',
    appVersion: '0.1.0',
    appContactInfo: 'Borewit'
  });

  const artist = document.getElementById('artist').value;
  const release = document.getElementById('release').value;

  const releaseGroup = await findReleaseGroup(mbApi, artist, release);
  if (!releaseGroup) {
    throw new Error(`No release group found for ${artist} – ${release}`);
  }

  console.log(`Using Release Group MBID=${releaseGroup.id}`);
  await findAllRelatedArtists(mbApi, releaseGroup.id);
}

function handleFind() {
  resolveArtists().catch(error =&gt; console.log(error.message));
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;html&gt;

&lt;head&gt;
  &lt;title&gt;Find all artist relations of Queen - Made in Heaven&lt;/title&gt;
&lt;/head&gt;

&lt;body&gt;
  &lt;h3&gt;Find all artist relations of Queen - Made in Heaven&lt;/h3&gt;
  Artist: &lt;input id="artist" value="Queen"/&gt;
    Release: &lt;input id="release" value="Made in Heaven"/&gt;
  &lt;button onclick="handleFind()"&gt;Find related artists&lt;/button&gt;
&lt;/body&gt;

&lt;/html&gt;</code></pre>
